// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.layerimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.bus.BrainEventimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.llm.cache.CacheResultimport com.roshan.persona.brain.llm.cache.SemanticLlmCacheimport com.roshan.persona.brain.llm.context.ContextInjectorimport com.roshan.persona.brain.llm.guardrails.GuardrailDecisionimport com.roshan.persona.brain.llm.guardrails.LocalLlmGuardrailsimport com.roshan.persona.brain.llm.provider.FinishReasonimport com.roshan.persona.brain.llm.provider.GenerationConfigimport com.roshan.persona.brain.llm.provider.GenerationResultimport com.roshan.persona.brain.llm.provider.LocalLlmProviderimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport kotlinx.coroutines.withTimeoutOrNullimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Layer 3: Local LLM. * * Orchestrates on-device LLM inference via the following pipeline: * *   1. **Guardrail check** — thermal, RAM, battery (Fixes #24). If device is *      too hot / out of RAM / low battery → defer to cloud (Layer 4) without *      ever invoking the LLM. * *   2. **Cache lookup** — compute prompt embedding, look up in *      [SemanticLlmCache]. If hit with similarity > threshold → return cached *      response instantly. Privacy: cache lives on-device only. * *   3. **Context injection** — [ContextInjector.buildPrompt] assembles *      persona + user context + ambient + history + memories + KG + tools + *      constitutional rules + user input into a single prompt. * *   4. **Generation** — call [LocalLlmProvider.generate] with streaming *      token callback (for UI). Enforced via [BrainBudget.maxLatencyMs] *      timeout (default 5s). * *   5. **Cache store** — store the (prompt embedding → response) pair in *      the cache for future semantic hits. * *   6. **Privacy fix (Fixes #6)** — if the response has low confidence *      (e.g., short answer, finish_reason=LENGTH, or repetition detected), *      the layer returns [SkillOutput.Partial] with a warning that offers *      the user an opt-in to verify via cloud. The cloud is **NEVER** called *      automatically by this layer. * * ## Failure Modes * *   - Provider not loaded → load() first. If load fails → return Failure. *   - Provider OOM (KV cache full) → return Failure with Llm.OutOfMemory, *     orchestrator can defer to cloud. *   - Provider context overflow → return Failure with Llm.ContextOverflow, *     orchestrator can retry with trimmed prompt or defer to cloud. *   - Timeout exceeded → return Failure with Llm.Timeout, orchestrator can *     defer to cloud. *   - Any other exception → return Failure with AppError.Unknown. * * ## Privacy Contract * *   - All data stays on device (local LLM is by definition private). *   - Cache is on-device only, never synced. *   - No automatic cloud fallback (Fixes #6). *   - User must explicitly opt-in to cloud verification via the Partial *     warning's offer. * * @see <a href="docs/spec/module2-spec-review.pdf">§7 Layer 3</a> * @see LocalLlmGuardrails * @see SemanticLlmCache * @see ContextInjector */@Singletonclass LocalLlmLayer @Inject constructor(    private val provider: LocalLlmProvider,    private val guardrails: LocalLlmGuardrails,    private val cache: SemanticLlmCache?,    private val contextInjector: ContextInjector,    private val brainBus: BrainBus,    private val embeddingModelVersion: String,    private val lowConfidenceMinTokens: Int,    private val lowConfidenceRepetitionThreshold: Float,) {    /**     * Process [userInput] through the local LLM layer.     *     * @param userInput the user's text input (already context-resolved by L0)     * @param context the brain context (used for budget, persona, telemetry)     * @param generationConfig LLM sampling params (default = BALANCED)     * @param onToken streaming callback for each generated token (UI updates)     * @return [SkillOutput.Success] / [SkillOutput.Partial] / [SkillOutput.Failure]     */    suspend fun process(        userInput: String,        context: BrainContext,        generationConfig: GenerationConfig = GenerationConfig.BALANCED,        onToken: (String) -> Unit = {},    ): Result<SkillOutput> {        val startNanos = System.nanoTime()        val correlationId = context.correlationId        // ─── Step 1: Guardrail check ─────────────────────────────────────        val guardrailDecision = guardrails.shouldRunLlm(            device = context.deviceContext,            provider = provider,        )        if (guardrailDecision is GuardrailDecision.Defer) {            Timber.tag("NOUS.L3").w("Guardrail defer: %s", guardrailDecision.reason)            return Result.Success(                data = SkillOutput.Failure(                    error = AppError.Llm.OutOfMemory(                        modelId = provider.modelId,                        requiredMb = (provider.modelSizeBytes / (1024 * 1024) * 2).toInt(),                    ),                    userMessage = "Local AI can't run right now: ${guardrailDecision.reason}. " +                        "I can try the cloud if you've enabled it in Settings → Privacy.",                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,                metadata = mapOf(                    "guardrail_reason" to guardrailDecision.reason,                    "defer_to" to guardrailDecision.deferTo.name,                ),            )        }        // ─── Step 2: Ensure provider is loaded ───────────────────────────        if (!provider.isLoaded) {            val loadResult = provider.load()            if (loadResult is Result.Failure) {                brainBus.emit(BrainEvent.LlmCallFailed(                    provider = PROVIDER_LOCAL,                    modelId = provider.modelId,                    error = loadResult.error,                    correlationId = correlationId,                ))                return Result.Failure(                    error = loadResult.error,                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }        }        // ─── Step 3: Build full prompt with context injection ────────────        val promptBuild = contextInjector.buildPrompt(            userInput = userInput,            context = context,            maxTokens = (provider.contextLength - generationConfig.maxTokens).coerceAtLeast(0),        )        // ─── Step 4: Cache lookup (semantic) ─────────────────────────────        var cacheHit: CacheResult.Hit? = null        if (cache != null) {            val embedResult = provider.embed(userInput)            if (embedResult is Result.Success) {                val lookupResult = cache.lookup(userInput, embedResult.data)                if (lookupResult is Result.Success) {                    val lookup = lookupResult.data                    if (lookup is CacheResult.Hit) {                        cacheHit = lookup                        Timber.tag("NOUS.L3").v(                            "Cache hit (sim=%.3f, %dms old)",                            lookup.similarity,                            System.currentTimeMillis() - lookup.cachedAt.toEpochMilli(),                        )                    }                }            }        }        if (cacheHit != null) {            // Stream cached response as a single "token" for UI consistency            onToken(cacheHit.response)            return Result.Success(                data = SkillOutput.Success(                    message = cacheHit.response,                    data = mapOf(                        "cache_hit" to "true",                        "cache_similarity" to cacheHit.similarity.toString(),                        "model_id" to provider.modelId,                    ),                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,                metadata = mapOf(                    "cache" to "hit",                    "similarity" to cacheHit.similarity.toString(),                ),            )        }        // ─── Step 5: Generate (with budget timeout) ──────────────────────        brainBus.emit(BrainEvent.LlmCallStarted(            provider = PROVIDER_LOCAL,            modelId = provider.modelId,            correlationId = correlationId,        ))        val generationTimeoutMs = context.budget.maxLatencyMs        val generationResult = withTimeoutOrNull(generationTimeoutMs) {            provider.generate(                prompt = promptBuild.prompt,                config = generationConfig,                onToken = onToken,            )        }        if (generationResult == null) {            // Timeout            val error = AppError.Llm.OutOfMemory(                modelId = provider.modelId,                requiredMb = (provider.modelSizeBytes / (1024 * 1024) * 2).toInt(),            )            // Use a more specific timeout error if available — fallback to Llm.OOM            val timeoutError = AppError.Llm.RateLimited(                provider = PROVIDER_LOCAL,                retryAfterMs = 5_000L,            )            brainBus.emit(BrainEvent.LlmCallFailed(                provider = PROVIDER_LOCAL,                modelId = provider.modelId,                error = timeoutError,                correlationId = correlationId,            ))            return Result.Failure(                error = timeoutError,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        when (generationResult) {            is Result.Failure -> {                brainBus.emit(BrainEvent.LlmCallFailed(                    provider = PROVIDER_LOCAL,                    modelId = provider.modelId,                    error = generationResult.error,                    correlationId = correlationId,                ))                return Result.Failure(                    error = generationResult.error,                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            is Result.Success -> { /* fall through */ }            is Result.Partial -> { /* shouldn't happen from generate(), but handle */ }        }        // Safe extraction: we already handled Failure above (returned early).        val generation = when (generationResult) {            is Result.Success -> generationResult.data            is Result.Partial -> generationResult.data            is Result.Failure -> return Result.Failure(                error = generationResult.error,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        brainBus.emit(BrainEvent.LlmCallCompleted(            provider = PROVIDER_LOCAL,            modelId = provider.modelId,            tokensGenerated = generation.tokensGenerated,            durationMs = generation.durationMs,            costUsd = 0f,  // local LLM is free            correlationId = correlationId,        ))        // ─── Step 6: Cache store (async, non-blocking) ───────────────────        if (cache != null && generation.tokensGenerated > 0) {            val embedResult = provider.embed(userInput)            if (embedResult is Result.Success) {                // Fire-and-forget — cache write failure is non-fatal                try {                    cache.store(                        prompt = userInput,                        response = generation.text,                        embedding = embedResult.data,                        modelVersion = embeddingModelVersion,                    )                } catch (t: Throwable) {                    Timber.tag("NOUS.L3").w(t, "Cache store failed (non-fatal)")                }            }        }        // ─── Step 7: Confidence check (Privacy fix #6) ───────────────────        val isLowConfidence = isLowConfidence(generation)        val skillOutput = if (isLowConfidence) {            // DO NOT auto-defer to cloud. Return Partial with opt-in offer.            SkillOutput.Partial(                message = generation.text,                warnings = listOf(                    "I'm not fully confident in this answer. " +                        "Tap to verify with cloud (sends data, requires opt-in).",                ),                data = mapOf(                    "model_id" to provider.modelId,                    "tokens_generated" to generation.tokensGenerated.toString(),                    "tokens_per_second" to generation.tokensPerSecond.toString(),                    "finish_reason" to generation.finishReason.name,                    "low_confidence" to "true",                    "cache_hit" to "false",                    "prompt_tokens" to promptBuild.estimatedTokens.toString(),                ),            )        } else {            SkillOutput.Success(                message = generation.text,                data = mapOf(                    "model_id" to provider.modelId,                    "tokens_generated" to generation.tokensGenerated.toString(),                    "tokens_per_second" to generation.tokensPerSecond.toString(),                    "finish_reason" to generation.finishReason.name,                    "cache_hit" to "false",                    "prompt_tokens" to promptBuild.estimatedTokens.toString(),                ),            )        }        return Result.Success(            data = skillOutput,            correlationId = correlationId,            durationNanos = System.nanoTime() - startNanos,            metadata = mapOf(                "model" to provider.modelId,                "tokens" to generation.tokensGenerated.toString(),                "tps" to generation.tokensPerSecond.toString(),                "low_confidence" to isLowConfidence.toString(),                "cache" to "miss",                "prompt_tokens_est" to promptBuild.estimatedTokens.toString(),            ),        )    }    /**     * Heuristic low-confidence detector.     *     * Flags:     *   - tokensGenerated below [lowConfidenceMinTokens] (likely truncated)     *   - finishReason = LENGTH (hit maxTokens, possibly incomplete)     *   - finishReason = ERROR (model error during generation)     *   - finishReason = CONTEXT_OVERFLOW (input too long)     *   - High repetition ratio (> [lowConfidenceRepetitionThreshold])     *     * @return true if the response is considered low-confidence     */    private fun isLowConfidence(result: GenerationResult): Boolean {        if (result.tokensGenerated < lowConfidenceMinTokens) return true        if (result.finishReason == FinishReason.LENGTH) return true        if (result.finishReason == FinishReason.ERROR) return true        if (result.finishReason == FinishReason.CONTEXT_OVERFLOW) return true        if (result.finishReason == FinishReason.OOM) return true        // Repetition check: split text into words, count unique ratio        val words = result.text.split(Regex("\\s+")).filter { it.isNotBlank() }        if (words.size >= 10) {            val unique = words.toSet().size            val ratio = unique.toFloat() / words.size            if (ratio < lowConfidenceRepetitionThreshold) return true        }        return false    }    companion object {        const val PROVIDER_LOCAL = "local"        /** Default embedding model version (for cache migration safety). */        const val DEFAULT_EMBEDDING_VERSION = "minilm-l6-v1.0"        /** If generated response has fewer than this many tokens, flag as low-confidence. */        const val DEFAULT_LOW_CONFIDENCE_MIN_TOKENS = 10        /** If word-unique-ratio < this, flag as low-confidence (likely stuck repeating). */        const val DEFAULT_REPETITION_THRESHOLD = 0.4f    }}